  private resolveCriterionIdentity(
    criterion: CriterionVerdictInput,
    ordinal: number,
    identities: string[],
  ): string {
    if (criterion.hasExplicitId && criterion.id.trim()) {
      identities[ordinal - 1] = criterion.id.trim();
      return criterion.id.trim();
    }

    const frozen = identities[ordinal - 1];
    if (frozen) {
      return frozen;
    }

    const generated = `criterion-${ordinal}`;
    identities[ordinal - 1] = generated;
    return generated;
  }

  private writeCriterionEvidenceArtifact(
    repoCwd: string,
    runId: string,
    issueId: IssueId,
