    const criterionDir = join(
      repoCwd,
      CRITERION_EVIDENCE_DIR,
      this.sanitizePathSegment(runId),
      `issue-${this.sanitizePathSegment(String(issueId))}`,
      this.sanitizePathSegment(criterionId),
    );
    if (!existsSync(criterionDir)) {
      mkdirSync(criterionDir, { recursive: true });
    }

    const hash = createHash("sha256").update(stdout).digest("hex").slice(0, 12);
    const relativePath = join(
      CRITERION_EVIDENCE_DIR,
      this.sanitizePathSegment(runId),
      `issue-${this.sanitizePathSegment(String(issueId))}`,
      this.sanitizePathSegment(criterionId),
      `${hash}.txt`,
    );
    const absolutePath = join(repoCwd, relativePath);
    if (!existsSync(absolutePath)) {
      const tmpPath = absolutePath + ".tmp";
      writeFileSync(tmpPath, stdout, "utf8");
      renameSync(tmpPath, absolutePath);
    }
    return relativePath;
  }

