/**
 * Loop Run coordinator.
 *
 * One instance per {@link ralphLoop} invocation. Owns the lifecycle of a
 * single run as the sole authoritative writer of the Durable Loop Run
 * Tracker, and announces past-tense facts to in-process subscribers after
 * each atomic write succeeds.
 *
 * See ADR-0007. The coordinator is introduced under a strangler migration:
 * methods are added here as joints are ported from `ralphLoop`. Initial
 * surface covers task phase transitions, scheduler progress, whole-run
 * review phase, and run completion. Snapshot/rollback and panic-undo
 * orchestration are part of the planned vocabulary in
 * `./events.ts` and will be added as those joints are rewired.
 */

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import type { LoopRunTracker } from "../utils/loop-run-tracker.js";
import type { TaskPhase, RunSnapshot, ReviewPhase, IssueId, TaskMeta, PromptTranscriptManifestRef, PromptPhase, PromptClientKind, AgentExecutionUsage, UsageLedgerEntry, TerminalReason, PanicUndoState, CriterionVerdict, CriterionStatus, LiveSteeringRecord } from "./state.js";
import { applyLiveSteeringUpdate, type LiveSteeringStatusUpdate } from "./state.js";

// Re-export the status-update shape for callers that historically imported
// it from this module; the canonical home is `state.ts`.
export type { LiveSteeringStatusUpdate } from "./state.js";
import type { WorkspaceManager, RollbackResult } from "../utils/workspace.js";
import type {
  LoopRunEvent,
  LoopRunSubscriber,
  RunOutcome,
} from "./events.js";
import { buildUsageSummary } from "./usage.js";

const CRITERION_EVIDENCE_DIR = join(".ralph-loop", "criterion-evidence");

export interface CriterionVerdictInput extends CriterionVerdict {
  ordinal?: number;
  hasExplicitId?: boolean;
  stdout?: string | null;
}

export interface LoopRunOptions {
  /**
   * Authoritative durable tracker for this run. The Loop Run becomes its
